select * from (select DISTINCT * from (SELECT rild.PRODID prodid, rild.PROD_NAME prodName, rild.REP_TYPE repType, rfp.NAME repTypeName, rild.REP_NAME repName, case when rild.START_DATE is null or rild.START_DATE = rild.END_DATE then DATE_FORMAT(rild.END_DATE,'%Y-%m-%d') else CONCAT_WS( '',DATE_FORMAT(rild.START_DATE,'%Y-%m-%d') , '--',DATE_FORMAT(rild.END_DATE,'%Y-%m-%d')) end reportDate, rild.REVEAL_END_DATE revealEndDate, rild.EXEC_STATUS execStatus, DATE_FORMAT(rild.STR_EXEC_DATE,'%Y-%m-%d %h:%i:%s') startExecDate, DATE_FORMAT(rild.END_EXEC_DATE,'%Y-%m-%d %h:%i:%s') endExecDate, (case when rild.EXEC_STATUS = '01' then '01' else '02' end) execResult, rild.EXEC_RESULT execResultExplain, ril.JOB_NAME jobName FROM REP_INSTALL_LOG_DETAIL rild INNER JOIN REP_INSTALL_LOG ril ON rild.JOB_ID = ril.JOB_ID AND ril.STATUS = #{status,jdbcType=VARCHAR} LEFT JOIN REP_INFO ri ON rild.REP_ID = ri.REP_ID LEFT JOIN REP_FTP_PATH rfp ON ri.REPORT_CATEGORY = rfp.ID
LEFT JOIN ( SELECT rep_id, group_concat(ERRORMSG ORDER BY rep_id separator ':') as errormsg FROM REP_CHECK_ERRMSG GROUP BY rep_id ) checks on checks.rep_id = rild.id WHERE rild.STATUS = #{status,jdbcType=VARCHAR}
AND rild.JOB_ID in
#{item}
AND rild.PRODID IN
#{item}
AND rild.REP_NAME like concat(concat('%',#{repName,jdbcType=VARCHAR}),'%')
AND rild.EXEC_STATUS IN
#{item}
AND rild.EXEC_STATUS IN
#{item}
AND DATE_FORMAT(rild.STR_EXEC_DATE,'%Y-%m-%d') >= #{valDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(rild.END_EXEC_DATE,'%Y-%m-%d') <= #{valDateEnd,jdbcType=VARCHAR}
AND ri.REPORT_CATEGORY IN
#{item}
AND DATE_FORMAT(rild.REVEAL_END_DATE,'%Y-%m-%d') >= #{revealEndDateBegin,jdbcType=VARCHAR}
AND DATE_FORMAT(rild.REVEAL_END_DATE,'%Y-%m-%d') <= #{revealEndDateEnd,jdbcType=VARCHAR}
order by rild.UPDATE_TIME desc))where 1=1
